// Normalize and validate the incoming lead. Runs once per item.
// The Webhook node puts the POST payload under $json.body.
const body = $json.body ?? $json;

const clean = (value, max = 500) =>
  String(value ?? '').trim().replace(/\s+/g, ' ').slice(0, max);

const lead = {
  name: clean(body.name, 120),
  email: clean(body.email, 200).toLowerCase(),
  company: clean(body.company, 160),
  phone: clean(body.phone, 40).replace(/[^\d+]/g, ''),
  source: clean(body.source || 'website-form', 60),
  message: String(body.message ?? '').trim().slice(0, 4000),
};

const errors = [];
if (lead.name.length < 2) errors.push('name is required');
if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(lead.email)) errors.push('email is invalid');
if (lead.message.length < 10) errors.push('message must be at least 10 characters');
// Honeypot: the form has a hidden "website" field that only bots fill in.
if (clean(body.website)) errors.push('spam detected');

lead.lead_id = 'L-' + $now.toFormat('yyyyMMdd-HHmmss') + '-' + Math.random().toString(36).slice(2, 6);
lead.received_at = $now.toISO();

return { json: { ...lead, valid: errors.length === 0, errors } };

// Deterministic stand-in for the LLM step: same output schema as the AI workflow
// {category, urgency, budget_estimate, summary, suggested_reply}, no API key needed.
const lead = $json;
const text = (lead.message + ' ' + lead.company).toLowerCase();
// Whole-word match ("cart" must not match "Carter"); a trailing * marks a stem ("automat*").
const has = (words) => words.some((w) =>
  new RegExp('(^|[^a-z0-9áéíóúñ])' + w.replace('*', '').split('.').join('\\.') +
    (w.endsWith('*') ? '' : '(?![a-z0-9áéíóúñ])')).test(text));

// 1) Category by keyword
const rules = [
  ['ecommerce', ['shop', 'tienda', 'store', 'shopify', 'woocommerce', 'ecommerce', 'e-commerce', 'checkout', 'cart']],
  ['automation', ['automat*', 'n8n', 'zapier', 'make.com', 'workflow', 'integrat*', 'crm', 'chatbot', 'ai agent']],
  ['support', ['broken', 'error', 'bug', 'down', 'not working', 'no funciona', 'caido', 'caída', 'fix']],
  ['marketing', ['seo', 'ads', 'marketing', 'campaign', 'campaña', 'newsletter', 'social media', 'leads']],
  ['web_development', ['website', 'web', 'landing', 'página', 'pagina', 'app', 'redesign', 'wordpress']],
];
const category = (rules.find(([, words]) => has(words)) ?? ['other'])[0];

// 2) Urgency
let urgency = 'medium';
if (has(['urgent', 'urgente', 'asap', 'today', 'hoy', 'tomorrow', 'mañana', 'this week', 'esta semana', 'down', 'broken', 'caido', 'deadline', 'losing sales', 'perdiendo'])) urgency = 'high';
else if (has(['no rush', 'sin prisa', 'next quarter', 'next year', 'just exploring', 'solo informacion', 'curious', 'someday'])) urgency = 'low';

// 3) Budget: use a stated amount if present, else a typical range per category
const m = lead.message.match(/(\d[\d.,]*)\s*(k|K)?\s*(€|eur|euros|\$|usd|dollars)|(€|\$)\s*(\d[\d.,]*)\s*(k|K)?/);
let budget_estimate;
if (m) {
  const raw = (m[1] ?? m[5]).replace(/[.,](?=\d{3}\b)/g, '').replace(',', '.');
  const amount = Math.round(parseFloat(raw) * ((m[2] ?? m[6]) ? 1000 : 1));
  const cur = /\$|usd|dollar/i.test(m[0]) ? 'USD' : 'EUR';
  budget_estimate = amount + ' ' + cur + ' (stated)';
} else {
  budget_estimate = {
    web_development: '1500-4000 EUR', automation: '500-2500 EUR', ecommerce: '2500-8000 EUR',
    marketing: '300-1500 EUR / month', support: '150-600 EUR', other: 'unknown',
  }[category];
}

// 4) Summary: first sentence, trimmed
const first = lead.message.split(/(?<=[.!?])\s/)[0];
const summary = (lead.company ? lead.company + ': ' : '') + (first.length > 140 ? first.slice(0, 137) + '...' : first);

// 5) Suggested reply in the lead's language (very small heuristic)
const spanish = /\b(hola|necesito|quiero|tienda|gracias|nuestra|empresa|para|presupuesto)\b/i.test(lead.message);
const firstName = lead.name.split(' ')[0];
const topics = {
  web_development: ['your new website', 'tu nueva web'],
  automation: ['automating your processes', 'automatizar vuestros procesos'],
  ecommerce: ['your online shop', 'vuestra tienda online'],
  marketing: ['your marketing', 'vuestro marketing'],
  support: ['the issue you are facing', 'la incidencia que tenéis'],
  other: ['your project', 'tu proyecto'],
};
const [topicEn, topicEs] = topics[category];
const suggested_reply = spanish
  ? `Hola ${firstName}, gracias por escribirnos. Hemos leído tu mensaje sobre ${topicEs} y nos encantaría ayudarte${urgency === 'high' ? ' cuanto antes' : ''}. ¿Te viene bien una llamada de 20 minutos ${urgency === 'high' ? 'hoy o mañana' : 'esta semana'} para concretar alcance y plazos? Un saludo, el equipo de Acme Studio`
  : `Hi ${firstName}, thanks for reaching out. We read your message about ${topicEn} and would love to help${urgency === 'high' ? ' as soon as possible' : ''}. Would a 20-minute call ${urgency === 'high' ? 'today or tomorrow' : 'this week'} work to agree on scope and timeline? Best regards, the Acme Studio team`;

return { json: { ...lead, category, urgency, budget_estimate, summary, suggested_reply, classified_by: 'rules (mock)' } };

// In the real workflow this is a Telegram node. Here we just build the message
// so you can inspect it in the execution log.
return { json: { channel: 'telegram (mock)', text: `URGENT lead ${$json.lead_id}: ${$json.name} - ${$json.summary}` } };

// Stand-in for Google Sheets: keep the last 50 leads in workflow static data.
// Static data persists only for production (active workflow) executions.
const store = $getWorkflowStaticData('global');
store.leads = store.leads ?? [];
for (const item of $input.all()) {
  const { suggested_reply, ...row } = item.json;
  store.leads.unshift(row);
}
store.leads = store.leads.slice(0, 50);
return $input.all().map((i) => ({ json: { ...i.json, stored_leads: store.leads.length } }));

const store = $getWorkflowStaticData('global');
const leads = store.leads ?? [];
return [{ json: { count: leads.length, leads } }];
